/* page title + description (lyiweb_pages) */
UPDATE dbo.lyiweb_pages SET title_en = CASE WHEN ISNULL(title_en, N'') = N'' THEN N'L.Y. Industries — Full-Service Narrow Fabrics & Trims to Global Standards' ELSE title_en END, meta_desc_en = CASE WHEN ISNULL(meta_desc_en, N'') = N'' THEN N'L.Y. Industries is a full-service narrow fabric and trims manufacturer in Bangkok, founded in 1978 — elastics, woven tapes, drawcords, waistbands and silicone details for global sportswear brands, woven, knitted, dyed and finished in one factory.' ELSE meta_desc_en END WHERE slug = N'home';
UPDATE dbo.lyiweb_pages SET title_en = CASE WHEN ISNULL(title_en, N'') = N'' THEN N'About L.Y. Industries — Narrow Fabrics & Trims Manufacturer since 1978' ELSE title_en END, meta_desc_en = CASE WHEN ISNULL(meta_desc_en, N'') = N'' THEN N'L.Y. Industries Co., Ltd. has made narrow fabrics and trims in Bangkok since 1978 — elastics, woven tapes, knitted tapes, cords, waistbands and finishing for global sportswear and fashion brands.' ELSE meta_desc_en END WHERE slug = N'about';
UPDATE dbo.lyiweb_pages SET title_en = CASE WHEN ISNULL(title_en, N'') = N'' THEN N'Narrow Fabric & Trims Catalog — Elastics, Woven Tapes, Knitted Tapes, Cords | L.Y. Industries' ELSE title_en END, meta_desc_en = CASE WHEN ISNULL(meta_desc_en, N'') = N'' THEN N'Product catalog of L.Y. Industries, a full-service narrow fabric & trims maker in Bangkok — elastics, woven tapes, Raschel/crochet tapes, drawcords, elastic cords, waistbands and logo printing for sportswear, intimates and fashion, developed to your spec.' ELSE meta_desc_en END WHERE slug = N'catalog';
UPDATE dbo.lyiweb_pages SET title_en = CASE WHEN ISNULL(title_en, N'') = N'' THEN N'Contact L.Y. Industries — Narrow Fabric & Trims Manufacturer, Bangkok' ELSE title_en END, meta_desc_en = CASE WHEN ISNULL(meta_desc_en, N'') = N'' THEN N'Contact L.Y. Industries, full-service narrow fabric and trims manufacturer, at 124 Soi Ram Inthra 109, Phraya Suren Road, Bang Chan, Khlong Sam Wa, Bangkok 10510. Tel +66 2 517 0768 ext. 120, 121 · sales@lyindustries.com · LINE @lyindustries' ELSE meta_desc_en END WHERE slug = N'contact';

