UPDATE dbo.lyiweb_items SET data_en = N'{"title":"Quality yarns & raw materials","short":"Yarn","desc":"We select polyester, nylon and spandex yarns to suit the construction, stretch and hand feel each trim needs."}', updated_at = GETDATE() WHERE list_key = N'home.steps' AND data_th = N'{"title":"เส้นด้าย & วัตถุดิบคุณภาพ","short":"เส้นด้าย","desc":"คัดเลือกเส้นด้าย ทั้งโพลีเอสเตอร์ ไนลอน และสแปนเดกซ์ ให้เหมาะกับโครงสร้าง ความยืดหยุ่น และสัมผัสที่ต้องการของแต่ละชิ้นงาน"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"title":"Weaving / knitting / braiding","short":"Weave/Knit/Braid","desc":"Our machines handle a wide range of woven, knitted and braided constructions — from fine, soft trims to ones built for high tension."}', updated_at = GETDATE() WHERE list_key = N'home.steps' AND data_th = N'{"title":"ทอ / ถัก / ถักเชือก","short":"ทอ/ถัก/ถักเชือก","desc":"เครื่องจักรรองรับโครงสร้างงานทอ งานถัก และงานถักเชือกหลากหลายรูปแบบ ตั้งแต่งานละเอียด เนื้อนุ่ม ไปจนถึงงานที่ต้องการรับแรงสูง"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"title":"In-house dye house & lab","short":"Dyeing & lab","desc":"Automated dye dispensing with computer-controlled recipes, matching to fabric samples and Pantone codes, with lab dips for colour approval and colour quality kept to standard in every order lot."}', updated_at = GETDATE() WHERE list_key = N'home.steps' AND data_th = N'{"title":"โรงย้อมและห้องแล็บภายใน","short":"ย้อมสีและแล็บ","desc":"ระบบจ่ายสีย้อมอัตโนมัติ ควบคุมสูตรด้วยคอมพิวเตอร์ เทียบสีตามผ้าตัวอย่างและรหัส Pantone พร้อมจัดทำ Lab dip เพื่ออนุมัติสี ควบคุมคุณภาพสีตามมาตรฐานที่กำหนดในทุกล็อตการสั่งซื้อ"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"title":"Finishing","short":"Finishing","desc":"Screen and sublimation printing, cord tipping in silicone, metal and film, anti-slip silicone coating, cutting to length, and embossing/debossing of text and logos — ready to sew onto the garment."}', updated_at = GETDATE() WHERE list_key = N'home.steps' AND data_th = N'{"title":"Finishing — งานตกแต่งสำเร็จ","short":"Finishing","desc":"งานสกรีน พิมพ์ Sublimation ทำปลายเชือก (Tipping) ด้วยซิลิโคน โลหะ และฟิล์ม เคลือบซิลิโคนกันลื่น ตัดตามความยาว และปั๊มนูน–จม ทั้งตัวอักษรและโลโก้ พร้อมนำไปเย็บประกอบบนชิ้นงาน"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"title":"QC on every lot","short":"QC every lot","desc":"Quality checks and property tests in our in-house lab — tensile strength, stretch after washing and colourfastness — so every piece meets the required standard before delivery."}', updated_at = GETDATE() WHERE list_key = N'home.steps' AND data_th = N'{"title":"QC ตรวจสอบคุณภาพทุกล็อต","short":"QC ทุกล็อต","desc":"ตรวจสอบคุณภาพและทดสอบคุณสมบัติด้วยห้องแล็บภายใน ทั้งแรงดึง ความยืดหยุ่นหลังซัก และความคงทนของสี (Colorfastness) เพื่อให้ชิ้นงานผ่านเกณฑ์มาตรฐานที่กำหนดก่อนส่งมอบ"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"title":"On-time delivery, one supplier","short":"On-time delivery","desc":"One supplier responsible for quality along the whole chain, shortening lead time and removing coordination errors between separate subcontractors."}', updated_at = GETDATE() WHERE list_key = N'home.steps' AND data_th = N'{"title":"ส่งมอบตรงเวลา ซัพพลายเออร์เดียว","short":"ส่งมอบตรงเวลา","desc":"ซัพพลายเออร์รายเดียวรับผิดชอบคุณภาพตลอดสาย ลด lead time และตัดปัญหาความผิดพลาดในการประสานงานระหว่างโรงงานย่อย"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"title":"Elastic Webbing","desc":"Consistent stretch and excellent recovery that won’t go baggy after hundreds of washes — for waistbands, shoulder straps and activewear."}', updated_at = GETDATE() WHERE list_key = N'home.products' AND data_th = N'{"title":"ยางยืด / สายยืด (Elastic Webbing)","desc":"ยืดหยุ่นสม่ำเสมอ คืนรูปยอดเยี่ยม ไม่ย้วยหลังผ่านการซักนับร้อยครั้ง สำหรับขอบเอว สายบ่า และงาน activewear"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"title":"Woven Tape","desc":"Dense construction with high tensile strength that holds its shape — for bag straps, decorative bands and structural parts."}', updated_at = GETDATE() WHERE list_key = N'home.products' AND data_th = N'{"title":"เทปทอ (Woven Tape)","desc":"โครงสร้างแน่น ทนทานต่อแรงดึงสูง คงรูปได้ดีเยี่ยม สำหรับสายรัดกระเป๋า แถบตกแต่ง และชิ้นส่วนโครงสร้าง"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"title":"Raschel / Crochet Knitted Tape","desc":"Lightweight, extra soft and breathable — ideal for overlays and pieces worn directly against the skin."}', updated_at = GETDATE() WHERE list_key = N'home.products' AND data_th = N'{"title":"เทปถัก Raschel / Crochet","desc":"น้ำหนักเบา ผิวสัมผัสนุ่มเป็นพิเศษ ระบายอากาศได้ดี เหมาะสำหรับ overlay และชิ้นงานสัมผัสผิวหนังโดยตรง"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"title":"Cords & Elastic Cords","desc":"Round, flat, elastic and braided cords, with every kind of tipping (dipped silicone, logo-engraved metal, shrink film)."}', updated_at = GETDATE() WHERE list_key = N'home.products' AND data_th = N'{"title":"เชือก เชือกยางยืด (Cords & Elastic Cords)","desc":"เชือกกลม เชือกแบน เชือกยางยืด ถักเปีย พร้อมงาน tipping หัวเชือกครบทุกเทคนิค (ซิลิโคนจุ่ม, โลหะสลักโลโก้, ฟิล์มหด)"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"title":"Engineered Waistbands","desc":"The part the wearer feels every second — we control both softness against the skin and a secure, comfortable fit for sports shorts."}', updated_at = GETDATE() WHERE list_key = N'home.products' AND data_th = N'{"title":"ขอบเอว (Engineered Waistbands)","desc":"จุดที่ผู้สวมใส่รู้สึกในทุกวินาที ควบคุมทั้งความนุ่มนวลต่อผิวและแรงกระชับที่พอดีตัวสำหรับกางเกงกีฬา"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"title":"Finishing & Branding","desc":"Take your tapes further in function and branding — anti-slip silicone, heat-transfer printing, embossing, laser, hot/cold cutting and labels, combined to suit the use."}', updated_at = GETDATE() WHERE list_key = N'home.products' AND data_th = N'{"title":"งาน Finish หลากหลายแบบ (Finishing & Branding)","desc":"ต่อยอดเทปให้ครบทั้งฟังก์ชันและแบรนด์ — ซิลิโคนกันลื่น พิมพ์ลาย heat transfer ปั๊มนูน เลเซอร์ ตัดร้อน/ตัดเย็น ไปจนถึงงานป้ายเลเบล เลือกผสมได้ตามการใช้งาน"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"q":"What is your minimum order quantity (MOQ)?","a":"We accept small orders. The minimum depends on the type of trim, its construction and colour — from market tests and small collections to large production orders. For new development (R&D) we make a sample run to test function and colour before production. Send us your design or use case and our sales team will assess it."}', updated_at = GETDATE() WHERE list_key = N'home.faq' AND data_th = N'{"q":"สั่งผลิตขั้นต่ำ (MOQ) อยู่ที่เท่าไหร่?","a":"เรารองรับการสั่งผลิตจำนวนน้อยได้ ขั้นต่ำขึ้นอยู่กับประเภทชิ้นงาน โครงสร้าง และสี — ทั้งงานทดลองตลาด คอลเลกชันขนาดเล็ก ไปจนถึงออเดอร์ปริมาณมาก ส่วนงานพัฒนาใหม่ (R&D) เราจัดทำชิ้นงานตัวอย่าง (Sample Run) เพื่อทดสอบฟังก์ชันและสีก่อนผลิตจริงได้ ส่งแบบหรือโจทย์การใช้งานมาให้ทีมฝ่ายขายประเมินได้เลย"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"q":"Can you match a Pantone code or a physical sample?","a":"Yes. We have our own in-house dye house and an automated colour lab, supporting the Pantone Matching System (TCX), lab dips and matching to your physical samples, with colour difference (Delta-E) kept within the tolerances accepted by global sportswear brands."}', updated_at = GETDATE() WHERE list_key = N'home.faq' AND data_th = N'{"q":"เทียบสีตามรหัส Pantone หรือตัวอย่างจริงได้ไหม?","a":"ได้แน่นอนครับ โรงงานมีโรงย้อมมาตรฐานในตัวและห้องแล็บเทียบสีอัตโนมัติ รองรับทั้งระบบ Pantone Matching System (TCX), การทำ Lab-dip และการเทียบสีตามชิ้นงานจริงของลูกค้า พร้อมการันตีค่าความต่างของสี (Delta-E) ให้อยู่ในเกณฑ์มาตรฐานที่แบรนด์กีฬาระดับโลกยอมรับ"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"q":"How long do sampling and production take?","a":"Sample development takes about 7–14 working days after the design and shade are confirmed. A production lot takes about 20–30 working days, depending on quantity and the complexity of the finishing."}', updated_at = GETDATE() WHERE list_key = N'home.faq' AND data_th = N'{"q":"ระยะเวลาในการพัฒนาตัวอย่างและผลิตจริงใช้เวลากี่วัน?","a":"การทำชิ้นงานตัวอย่าง (Sample Development) ใช้เวลาประมาณ 7 – 14 วันทำการหลังยืนยันแบบและเฉดสี สำหรับการผลิตล็อตจริงใช้เวลาประมาณ 20 – 30 วันทำการ ขึ้นอยู่กับปริมาณและความซับซ้อนของเทคนิคการตกแต่ง (Finishing)"}' AND (data_en IS NULL OR data_en = N'');
UPDATE dbo.lyiweb_items SET data_en = N'{"q":"Do you offer custom development (OEM / ODM)?","a":"Yes. Our R&D team has more than 40 years of experience working with designers and sourcing managers of global sportswear brands — from advice on yarn construction and recycled yarns to tuning tension and making samples for real sewing tests."}', updated_at = GETDATE() WHERE list_key = N'home.faq' AND data_th = N'{"q":"รับบริการพัฒนาสินค้าตามแบบเฉพาะ (OEM / ODM) หรือไม่?","a":"รับครับ ทีมงาน R&D ของเรามีประสบการณ์กว่า 40 ปีในการร่วมงานกับดีไซเนอร์และผู้จัดการฝ่ายจัดซื้อของแบรนด์กีฬาระดับโลก ตั้งแต่การให้คำปรึกษาเรื่องโครงสร้างเส้นด้าย การเลือกใช้วัสดุรีไซเคิล (Recycled Yarn) การปรับแรงดึง ไปจนถึงการขึ้นตัวอย่างเพื่อทดสอบการเย็บจริง"}' AND (data_en IS NULL OR data_en = N'');

COMMIT TRANSACTION;
